	public void SecToTime(int sec){
		int h = 0,m = 0;

		while(sec >= 3600){
			h++;
			sec -= 3600;
		}

		while(sec >= 60){
			m++;
			sec -= 60;
		}

		System.out.println(h+":"+m+":"+sec);
	}
}

