			s = sc.nextLine();
			scanInt( s, intAry ) ;
		}
	}
	public static void scanInt( String str, int[] intAry ) {
		Pattern ptn = Pattern.compile( "([0-9]+)\\s+([0-9]+)");
		Matcher mch = ptn.matcher( str ) ;
		if ( mch.find() == true ) {
			intAry[0] = Integer.parseInt( mch.group(1) ) ;
			intAry[1] = Integer.parseInt( mch.group(2) ) ;
		}
	}
}

