			}else {
				if(process(i))
					text.append(" ").append(i);
			}
		}
		System.out.println(text.toString());
	}
	static boolean process(int i){
		if(i % 10 == 3){
			return true;
		}else{
			if(i / 10 == 0)
				return false;
			return process(i / 10);
		}
	}
