        int tmpGcd = 0;
        for (int i = 1; i <= K; i++){
            for (int j = 1; j <= K; j++){
                for (int k = 1; k <= K; k++){
                    tmpGcd = gcd(i, j);
                    sum += gcd(tmpGcd, k);
                }
            }
        }
