    }

    public static int gcd (int a, int b){
        int tmp = 0;
        if (a == 0) return b;
        if (b == 0) return a;
        if (a > b){
            tmp = a;
            a = b;
            b = tmp;
        }
        return gcd(b % a, a);
    }
}

