        int g = gcd(a,b);
        g = gcd(g,c);
    return g;
    }

    public static final int gcd(int a, int b) {

        if (a < b) {
            int tmp = a;
            a = b;
            b = tmp;
        }

        int r = -1;
        while (r != 0) {
            r = a % b;
            a = b;
            b = r;
        }

        return a;
    }


}

