  public static int GCD(int x, int y, int z) {

    while (x != y){
      if (x > y){
        x = x-y;
      }else{
        y = y -x;
      }
    }

    while (x != z){
      if (x > z){
        x = x-z;
      }else{
        z = z -x;
      }
    }    
    return z;
  }


}

