		int base = a;
		if(base > b) {
			base =b;
		}

		for(int i =base;i >=1;i--) {
			if(a % i !=0) {
				continue;
			}
			if(b % i !=0) {
				continue;
			}
			return i;
		}

		return 1;

	}
}

