   int gcd(int a,int b,int c){
     int min = a;
     int num = 1;
     if(a>b&&b<=c)
       min = b;
     else if(a>b&&b>c)
       min = c;

     for(int i=1;i<=min;i++){
       if(a%i==0&&b%i==0&&c%i==0)
         num = i;
     }
     return num;
   }
