  public static int find(int a,int b,int c){
    int min = a;
    if (a>b){
      min = b;
    }
    if (min>c){
      min = c;
    }

    int l = min;
    while (l>1){
      if ((a%l == 0) && (b%l == 0) && (c%l == 0)){
        return l;
      }
      l -= 1;
    }
    return l;
  }

}

