        // 解答処理
        solve();
    }

    private void solve() {
        int ans = 0;
        for (int i = 1; i <= k; i++) {
            for (int j = 1; j <= k; j++) {
                for (int l = 1; l <= k; l++) {
                    ans += gcd(i, gcd(j, l));
                }
            }    
        }
        System.out.println(ans);
    }

    private int gcd(int a, int b) {
        int r = 0;
        if (a < b) {
            int tmp;
            tmp = a;
            a = b;
            b = tmp;
        }
        r = a % b;
        while (r != 0) {
            a = b;
