                vote.put(name,temp+1);
            }
            else{
                vote.put(name,1);
            }
        }
        int max = 0;
        for(String s:vote.keySet()){
            max = Math.max(max,vote.get(s));
        }
        ArrayList<String> names = new ArrayList<>();

        for(String s:vote.keySet()){
            if(vote.get(s)==max) names.add(s);
        }
        Collections.sort(names);

        for(String s:names) System.out.println(s);
    }

}

