import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        List<Integer> numsListA = new ArrayList<Integer>();
        List<Integer> numsListB = new ArrayList<Integer>();
        List<Integer> numsListC = new ArrayList<Integer>();
        int score = 0;

        Scanner scan = new Scanner(System.in);

        int n = scan.nextInt();                     //N品の料理を食べる
        for(int i = 0; i < n; i++) {                //N回scanします ListA
            numsListA.add(scan.nextInt());
        }
        for(int i = 0; i < n; i++) {                //N回scanします ListB
            numsListB.add(scan.nextInt());
        }
        for(int i = 0; i < n - 1; i++) {            //N-1回scanします ListC
            numsListC.add(scan.nextInt());
        }

        for (int i = 0; i < n; i++) {               //ListB満足度をscoreにSUM
            score += numsListB.get(numsListA.get(i) - 1);
        }

        for (int i = 0; i < n - 1; i++) {           //ListCボーナスをscoreにSUM
            if(numsListA.get(i + 1) - numsListA.get(i) == 1) {
                score += numsListC.get(numsListA.get(i)- 1);
            }
        }

        System.out.println(score);
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = getInt(sc);
		int[] a = getIntArray(sc);
		int[] b = getIntArray(sc);
		int[] c = getIntArray(sc);

		int preOrder = -1;
		int satisfaction = 0;
		for (int i = 0; i < n; i++) {
			int order = a[i];
			satisfaction += b[order - 1];
			if (order - preOrder == 1) {
				satisfaction += c[order - 2];
			}
			preOrder = order;
		}
		System.out.println(satisfaction);
	}

	/**
	 * *汎用メソッド<br>
	 * 入力した配列に対する順列を取得
	 *
	 * @param numArray
	 * @return
	 */
	private static List<Integer[]> getPermutation(int[] numArray) {
		List<Integer[]> permutation = new ArrayList<>();
		Integer[] ans = new Integer[numArray.length];
		boolean[] used = new boolean[numArray.length];

		return buildPermutaion(permutation, numArray, ans, used, 0);
	}

	/**
	 * *汎用メソッド(内部)<br>
	 * 入力した配列に対する順列を作成
	 *
	 * @param list
	 * @param numArray
	 * @param ans
	 * @param used
	 * @param depth
	 * @return
	 */
	private static List<Integer[]> buildPermutaion(List<Integer[]> list, int[] numArray, Integer[] ans, boolean[] used,
			int depth) {

		// 全部使い切った時=>できた順列を返す
		if (depth == numArray.length) {
			list.add(ans.clone());
			return list;
		}
		// 使い切っていない場合

		for (int i = 0; i < numArray.length; i++) {
			if (used[i]) {
				continue;
			}
			ans[depth] = numArray[i];
			used[i] = true;
			list = buildPermutaion(list, numArray, ans, used, depth + 1);

			used[i] = false;
		}

		return list;
	}

	/**
	 * *汎用メソッド <br>
	 * スキャナーからの入力値をlongで返却
	 *
	 * @return
	 */
	public static long getLong(Scanner sc) {

		return Long.parseLong(sc.next());
	}

	/**
	 * *汎用メソッド <br>
	 * スキャナーからの入力値をintで返却
	 *
	 * @return
	 */
	public static int getInt(Scanner sc) {

		return Integer.parseInt(sc.next());
	}

	/**
	 * *汎用メソッド <br>
	 * スキャナーからの入力値をStringで返却
	 *
	 * @return
	 */
	public static String getString(Scanner sc) {

		return sc.next();
	}

	/**
	 * *汎用メソッド <br>
	 * スキャナーからの入力値をint配列で返却
	 *
	 * @return
	 */
	public static int[] getIntArray(Scanner sc) {
		String line = "";
		// 直前にnext()を実行していると改行コードだけ取ってしまうのでその対策
		while (line.equals("")) {
			line = sc.nextLine();
		}

		String[] strArray = line.split(" ");
		int[] intArray = new int[strArray.length];
		for (int i = 0; i < strArray.length; i++) {
			intArray[i] = Integer.parseInt(strArray[i]);
		}
		return intArray;
	}

}

