    if (map.size() != 2) {
      System.out.println("No");
      return;
    }
    for (Map.Entry<Character, Integer> entry : map.entrySet()) {
      if (entry.getValue() != 2) {
        System.out.println("No");
        return;
      }
    }
    System.out.println("Yes");
  }  
}

