                dp[1] = 0;
            } else {
                dp[1] = 1;
            }
            for (int i = 2; i <= N; i++) {
                if (!broken[i - 1]) dp[i] += dp[i - 1];
                if (!broken[i - 2]) dp[i] += dp[i - 2];
                dp[i] %= mod;
