		if(M != 0) {
			F.add(fib[a[1]]);
			F.add(fib[N-a[M]]);
		}
		else
			F.add(fib[N+1]);
		long ans = 1;
		for(int i = 0; i < F.size(); i++) {
			ans *= F.get(i);
			ans %= 1000000007;
		}
