import java.util.*;
import java.io.*;
public class Main {
    public static void main(String args[]) {

      Scanner sc = new Scanner(System.in);
      PrintWriter w = new PrintWriter(System.out);
      //Input Part
      int n = sc.nextInt();
      int k = sc.nextInt();
      int height[] = new int[n];
      for(int i = 0; i < n; i++)
      {
          height[i] = sc.nextInt();
      }

      //Logic Part
      int dp[] = new int[n];
      dp[0] = 0;
      dp[1] = Math.abs(height[1] - height[0]);
      for(int i = 2; i < n; i++)
      {
          dp[i] = dp[i-1] + Math.abs(height[i] - height[i-1]);
          for(int j = 2; j <= k; j++)
          {
              if(j <= i && j < n)
              {
                  dp[i] = Math.min(dp[i], dp[i-j] + Math.abs(height[i] - height[i-j]));
              }
          }
      }
      w.println(dp[n-1]);
      w.close();
    }
}

import java.util.Scanner;


public class Main {

	static int k;
	static long n;
	static long[] stones;
	static long memo[];

	public static void main(String[] args) {

		String input1 = "";
		String input2 = "";
		Scanner scanner = new Scanner(System.in);
		input1 = scanner.nextLine();
		input2 = scanner.nextLine();
		String[] n2 = input1.split(" ");

		n = Long.parseLong(n2[0]);
		k = Integer.parseInt(n2[1]);
		String[] arr = input2.split(" ");
		stones = new long[(int) n];
		for (int i = 0; i < arr.length; i++) {
			stones[i] = Integer.parseInt(arr[i]);
		}

		memo = new long[(int) n];
		for (int i = 0; i < memo.length; i++) {
			memo[i] = -1;
		}
		System.out.println(getMinCostStone(0));
		scanner.close();
	}

	public static long getMinCostStone(int i) {
		if (i == stones.length - 1) {
			return 0;
		}
		long cost = memo[i];

		if (cost != -1) {
			return cost;
		}
		cost = (long) 1e18;
		memo[i] = cost;
		if (i != stones.length - k) {
			for (int j = 1; j <= k; j++) {
				if (i + j < stones.length) {
					cost = Long.min(cost, getMinCostStone(i + j) + Math.abs(stones[i] - stones[i + j]));
					memo[i] = cost;
				}
			}
		}
		return memo[i] = cost;
	}

}

