		Map<String, Deque<String>> deq = new HashMap<>();
		String[] participants = new String[] {"a", "b", "c"};
		for (int i = 0; i < 3; i++) {
			String s = sc.next();
			deq.put(participants[i], new ArrayDeque<>());
			for (int j = 0; j < s.length(); j++) {
				deq.get(participants[i]).addLast(s.charAt(j) + "");
