        ls = ls + fs;
      }else if(fs.equals("B")){
        if(!(ls.equals(""))){
          lslen = ls.length();
          lslen -= 1;
          ls = ls.substring(0,lslen);
        }
      }
    }
    System.out.println(ls);
  }
}

